const shadowLog = {
  shadow_mode: true, logged_at: new Date().toISOString(), ticket_id: $json.id,
  ai_decision: {category: $json.ai_classification?.category || $json.category, priority: $json.ai_classification?.priority || $json.priority, urgency: $json.ai_classification?.urgency || $json.urgency, suggested_resolution: $json.ai_classification?.suggested_resolution || '', confidence: $json.ai_classification?.confidence || 0, ai_bypassed: $json.ai_bypassed || false},
  human_review: {required: $json.requires_human_review || false, decision: $json.human_decision || null, reviewer: $json.reviewer || null},
  servicenow_action: {would_create: !$json.is_update, would_update: $json.is_update, sys_id: $json.sys_id},
  validation: {pending_human_comparison: true, actual_human_action: null}
};
console.log('SHADOW_MODE_LOG:', JSON.stringify(shadowLog));
return {json: {...shadowLog, status: 'shadow_logged', message: 'Shadow mode active - no ServiceNow changes made'}};

const result = {
  ticket_id: $json.id || $input.first()?.json?.id,
  sys_id: $json.result?.sys_id || $input.first()?.json?.sys_id,
  servicenow_number: $json.result?.number || null,
  action_taken: $input.first()?.json?.is_update ? 'updated' : 'created',
  action_timestamp: new Date().toISOString(),
  ticket_data: {title: $input.first()?.json?.title, category: $input.first()?.json?.ai_classification?.category, priority: $input.first()?.json?.ai_classification?.priority, confidence: $input.first()?.json?.ai_classification?.confidence}
};
console.log('SERVICENOW_ACTION:', JSON.stringify(result));
return {json: result};

const auditEntry = {
  audit_id: `AUD-${Date.now()}`,
  timestamp: new Date().toISOString(),
  workflow_execution_id: $execution.id,
  ticket: {id: $json.ticket_id || $json.id, sys_id: $json.sys_id, servicenow_number: $json.servicenow_number},
  processing: {shadow_mode: $json.shadow_mode || false, ai_bypassed: $json.ai_bypassed || false, human_reviewed: !!$json.human_decision, action_taken: $json.action_taken || $json.status || 'completed'},
  ai_metrics: {confidence: $json.ai_decision?.confidence || $json.ticket_data?.confidence, category: $json.ai_decision?.category || $json.ticket_data?.category},
  status: 'completed'
};
console.log('AUDIT_LOG:', JSON.stringify(auditEntry));
return {json: auditEntry};

const errorResponse = {success: false, error: 'Validation failed', validation_errors: $json.validation_errors, ticket_id: $json.id, received_at: $json.received_at};
console.log('VALIDATION_ERROR:', JSON.stringify(errorResponse));
return {json: errorResponse};
